mapper.select:
SELECT HOUB.UNIT_ID unitId, HOUB.UNIT_CODE unitCode, HOUB.PARENT_unit_ID parentUnitId, HOUB.unit_NAME unitName, HOUB.ENABLED_FLAG enabledFlag, HOUB.COMPANY_ID companyId, ( SELECT SCVT2.MEANING FROM SYS_CODE_VALUE_B SCVB2 INNER JOIN SYS_CODE_B SCB2 ON ( SCB2.CODE_ID = SCVB2.CODE_ID AND SCB2. CODE = 'FND.UNIT_TYPE' ) LEFT JOIN SYS_CODE_VALUE_TL SCVT2 ON ( SCVB2.CODE_VALUE_ID = SCVT2.CODE_VALUE_ID AND SCVT2.LANG = #{request.locale,jdbcType=VARCHAR,javaType=java.lang.String}) WHERE SCVB2.VALUE = HOUB.UNIT_TYPE ) unitTypeName, ( CASE WHEN PARENT_UNIT_ID IS NULL THEN '' ELSE (SELECT FOU.UNIT_NAME FROM FND_ORG_UNIT FOU WHERE FOU.UNIT_ID = HOUB.PARENT_UNIT_ID) END ) parentName, ( CASE WHEN HOUB.COMPANY_ID IS NULL THEN '' ELSE (SELECT FC.COMPANY_FULL_NAME FROM FND_COMPANY FC WHERE FC.COMPANY_ID = HOUB.COMPANY_ID) END ) companyName FROM FND_ORG_UNIT HOUB
AND HOUB.UNIT_CODE LIKE CONCAT('%', CONCAT(#{unitCode,jdbcType=VARCHAR}, '%'))
AND HOUB.UNIT_NAME LIKE CONCAT('%', CONCAT(#{unitName,jdbcType=VARCHAR}, '%'))
AND HOUB.COMPANY_ID = #{companyId}
AND HOUB.UNIT_ID = #{unitId}
ORDER BY HOUB.UNIT_ID ASC
